static void input_off(track_t *t, uint32_t note)
{
    if (!in_solo)
        fol_key(t, note, 0);                        /* ((2.1) one fewer holding its chord) */
    if (midi_note_held(t, note))
        return;
    if (cin_left) {                                 /* a kept note let go before step 1: recorded, then let go */
        uint32_t i = trk_index(t), k;
        for (k = 0; k < cin_n[i]; k++)
            if (cin_note[i][k] == note)
                cin_up[i] |= (uint8_t)(1u << k);
    }
    rec_release(t, note);
    if (!t->p[P_AMODE] || in_solo)
        take_note(t, note, 0);                      /* (Skiff: its end, for TAKES' holds) */
    if (!in_solo)                                   /* ((2.1, #74) a SOLO black key's never was the ARP's) */
        arp_remove(t, note);                        /* both: the note may have started in the */
    if (!t->p[P_AMODE] || !kb_sol_held(t, note))    /* other mode (ARP switched while held); ((2.1, #74) */
        trk_note_off(t, note);                      /* the ARP on: not one a SOLO black key sounds) */
}

/* the engine's own key map (DRUM's GM map, slices) for key k, -1 none */
static int32_t kb_engine(const track_t *t, uint32_t k)
{
    const engine_t *e = ENGINES[eng_idx(t->eng_req)];   /* (the engine it switches to) */
    return e->keys ? e->keys(t, k) : -1;
}

static void midi_expression_channel(uint32_t ch)
{
    uint32_t i, mask = midi_targets(ch);
    for (i = 0; i < NPART; i++)
        if (mask & (1u << i))
            midi_expression(&trk[i], midi_channel(ch));
}

/* track t's playing step has just ended (period: its DIV's step; t->seq_pos: how long ago, at the block's end): a
 * launch point (mode, at) is here */
static int launch_here(const track_t *t, uint32_t len, uint32_t period, uint32_t mode, uint32_t at)
{
    if (mode == LAUNCH_LOOP)
        return seq_pass_last(t, len);
    if (mode == LAUNCH_NOW || launch_steps >= at)
        return 1;
    return (at - launch_steps) * div_samples(2) - launch_pos + t->seq_pos < period / 2u;   /* (its line < half a step on) */
}

/* DIST: low cut -> drive (1x..8x, exponential) -> asymmetric soft clip
 * (a little bias = even harmonics) -> tone low-pass that closes with drive ->
 * make-up gain (straight into tanh over the full band, it would sound like a
 * broken digital fuzz). State per part (track_t dist_*). (Skiff phase 9) DRIVE's TYPE and TONE: above */
static void track_dist(track_t *t, int32_t *b, uint32_t n)
{
    int32_t d = t->p[P_DIST], i, g, k, mk, bias = 2400, b0;
    if (!d)
        return;                                         /* states kept: switching on does not click */
    g = 4096 + d * d * 2;                                /* Q12: 1x .. ~9x, gentle at first */
    k = DIST_TONE(32000 - d * 95, t);                    /* tone: transparent at low drive .. ~3 kHz, Q15 */
    mk = 30000 - d * 120;                                /* make-up */
    switch (t->p[P_DTYPE]) {
    case DT_HARD: dist_hard(t, b, n, g, k, mk); return;
    case DT_FOLD: dist_fold(t, b, n, g, k, mk); return;
    case DT_CRUSH: dist_crush(t, b, n, d, DIST_TONE(32700 - d * 40, t), 32000 - d * 20); return;
    case DT_FUZZ: dist_fuzz(t, b, n, g, k, mk); return;
    default: break;
    }
    b0 = softclip(bias);
    for (i = 0; i < (int32_t)n; i++) {
        int32_t x = b[i], y;
        t->dist_hp += (x - t->dist_hp + 64) >> 7;           /* ~55 Hz low cut: keep the bass out of the clipper */
        x = clamp(x - t->dist_hp, -230000, 230000);         /* (x >> 2) * g fits 32 bits; the clip is flat out there */
        y = ins_shape(IT_SOFT, (((x >> 2) * g) >> 10) + bias, 0) - b0;   /* >> 2 first: no overflow for loud poly */
        t->dist_lp1 += mulq15(y - t->dist_lp1, k);         /* two poles: tames the fizz */
        t->dist_lp2 += mulq15(t->dist_lp1 - t->dist_lp2, k);
        b[i] = mulq15(t->dist_lp2, mk);
    }
}

static void c1_parts(uint32_t arg)                      /* arg: the tracks (bit k = track k) | n << 8 */
{
    uint32_t i, n = arg >> 8;
    mixsum_t *sm = &mx[1];
    for (i = 0; i < n; i++)
        sm->l[i] = sm->r[i] = sm->c[i] = sm->d[i] = sm->v[i] = 0;
    for (i = 0; i < NPART; i++)
        if (arg >> i & 1u)
            mix_part(&trk[i], n, sm);
}

/* (2.0, D3) a record of a format of before by its magic: FUN1..FUN9, Felucca's FUNA, SKF1, SKF2. 2.0 keeps its bytes
 * (OLD FORMAT); the converter reads it (web/conv) */
static int proj_old_magic(uint32_t m) { return (m >= 0x46554E31u && m <= 0x46554E41u) || m == PROJ_MAGIC || m == PROJ_MAGIC2; }

/* after loading bank b (len bytes, -1 = none): wrong shape -> empty; each record's pattern inside its fields, as
 * UP_PUT and SAVE store it (flash or a restored backup may hold anything there) */
static void up_bank_check(uint32_t b, int len)
{
    up_bank_t *bk = &up_bank[b];
    uint32_t i, k;
    if (len != (int)sizeof *bk || bk->magic != UP_BANK_MAGIC || bk->rsize != sizeof(up_rec_t) ||
        bk->nslot != UP_PER_BANK)
        memset(bk, 0, sizeof *bk);
    for (i = 0; i < UP_PER_BANK; i++) {
        up_rec_t *r = &bk->r[i];
        if (!up_valid(r) || !up_pat(r))                 /* ((2.0) v6: no pattern, its bytes values) */
            continue;
#if FELUCCA_LEGACY
        up_migrate(r);
#endif
        for (k = 0; k < 16u; k++)
            if (up_grid(r))
                r->flags[k] &= r->note[k];          /* a drum grid: accents only on its hits */
            else
                up_pat_norm(&r->note[k], &r->flags[k]);
    }
}

static int bk_body(uint32_t i, const bk_hdr_t *h)  /* its payload -> bk_buf, the hash right: 0 */
{
    return bk_read(bk_sector(i) + 256u, bk_buf, BK_LEN) || proj_hash(bk_buf, BK_LEN) != h->sum ? -1 : 0;
}

/* (Skiff phase 5) a bit a track: its pattern came in without its automation (the 64 records full, bank.c): the pattern
 * keeps what it has stored (bank.c trk_keep), and the track takes no new records until another pattern comes in or
 * its automation is cleared */
static uint8_t motion_lost __attribute__((section(".pool")));   /* (.pool: off the ISR's merged globals) */
static void motion_clear(track_t *t)
{
    uint32_t f = motion_guard(), k = trk_index(t), i, n = 0;
    motion_lost &= (uint8_t)~(1u << k);            /* (cleared on purpose: nothing of it to keep) */
    motion_restore(t);
    for (i = 0; i < motion.count; i++)
        if ((motion.event[i].place >> 6) != k) motion.event[n++] = motion.event[i];
    memset(motion.event + n, 0, (MOTION_MAX - n) * sizeof motion.event[0]);
    motion.count = (uint8_t)n;
    motion.on &= (uint8_t)~(1u << k);
    motion_rebase(t);
    motion_full = 0;
    motion_unguard(f);
}

static void lists_clear(void)                          /* no lists, no patterns on the tracks */
{
    memset(&lists, 0, sizeof lists);
    memset(trk_pid, 0, sizeof trk_pid);
}

static void usb_start(void)                             /* boot, or main-loop retry while usb.up == 0 */
{
    usb.timeouts = 0;
    fm1_usb_reset();                                    /* reset whatever the ROM left */
    fm1_delay_ms(25);
    fm1_usb_attach(ep0buf);
    sie_wr(S_POWER, 0x60);
    sie_wr(S_INTRUSBE, 0x07);                           /* suspend, resume, reset (polled) */
    sie_wr(S_INTRTX1E, 0x01);
    sie_wr(S_INTRTX2E, 0);
    sie_wr(S_INTRRX1E, 0);
    sie_wr(S_INTRRX2E, 0);
    fm1_usb_ep_enable(0x1Fu);
    usb.up = usb.timeouts < 3u;                         /* a dead SIE leaves USB off */
}

static uint32_t pend_at(uint32_t id)                /* id's waiting copy, PEND_N none */
{
    uint32_t i;
    for (i = 0; i < PEND_N; i++)
        if (pend_id[i] == id % BK_POOL)
            return i;
    return PEND_N;
}

/* track k as a record (bk_rec): its steps, the sound's own timing, its automation (a pattern that came in without its
 * automation keeps its stored one: motion_lost). 0: a step no format holds */
static int trk_rec(uint32_t k)
{
    k %= NTRK;
    if (!bk_pack(bk_rec, &trk[k]))
        return 0;
    if (((motion_lost >> k) & 1u) && trk_pid[k])
        rec_motion_of(bk_rec, trk_pid[k] - 1u);
    return 1;
}

static void master_poll(void)
{
    int32_t a = fm1_adc_read(FM1_ADC_MASTER);
    if (a >= 0) {
        master_knob += (a * 16 - master_knob) / 8;
        song.master_q12 = master_of_pot((uint32_t)(master_knob / 16));
    }
}

static int ed_args_ok(uint32_t cmd, const uint8_t *a, uint32_t n)
{
    switch (cmd) {
    case ED_INFO: case ED_DUMP: case ED_SMP_INFO: case ED_PING:
    case ED_UI_STATE: case ED_UI_PALETTES:
        return !n;
    case ED_GET: case ED_DESC: case ED_PRESET: case ED_PROJECT: case ED_UP_LIST:
    case ED_TRACK_PARAM:
        return n == 2u || (cmd == ED_TRACK_PARAM && n == 4u);
    case ED_SET:
        return n == 4u;
    case ED_STEP_GET: case ED_NAMES: case ED_SMP_BEGIN: case ED_SMP_ERASE:
    case ED_UP_GET: case ED_UP_LOAD: case ED_UP_ERASE: case ED_WATCH: case ED_TRACK_DUMP: case ED_MENU_DESC:
        return n == 1u;
    case ED_MENU_SET:
        return n == 3u;
    case ED_TRANSPORT: case ED_PROJ_NAME:
        return ed_project_args_ok(cmd, a, n);
    case ED_POOL: case ED_LIST: case ED_PERFORM: case ED_LIST2:
        return ed_song_args_ok(cmd, a, n);
    case ED_KIT_GET:                                   /* (Skiff W3) a lane; a lane and its 15 values, each in range */
        return n == 1u && a[0] < 8u;
    case ED_KIT_PUT: {
        uint32_t i;
        if (n != 16u || a[0] >= 8u || a[1] > 3u || a[2] > DXF_HP || a[3] > 1u || a[4] > 3u || a[5] > 1u)
            return 0;
        for (i = 6; i < 16u; i++)
            if (a[i] > 127u)
                return 0;
        return 1;
    }
    case ED_STEP_SET:
        return n == 9u || n == 12u || (n == 13u && a[12] <= 100u) ||               /* notes only, or the complete grid extension, */
               (n == 14u && a[12] <= 100u && a[13] >= 1u && a[13] <= 4u) ||     /* its chance, its ratchet, */
               ((n == 17u || (n == 18u && a[17] <= 15u)) && a[12] <= 100u && a[13] >= 1u && a[13] <= 4u &&
                a[14] <= 1u && a[15] < TC_COUNT && a[16] <= 63u);               /* (Skiff W1) FLAM, COND, NUDGE,
                                                                                 * (2.0, #25) its ties */
    case ED_TRACK:
        return n <= 1u;
    case ED_TRACK_MIX:
        return n == 1u || n == 4u;
    case ED_TRACK_STEP:                                /* (a get, or the track and a STEP_SET's) */
        return n == 2u || ed_args_ok(ED_STEP_SET, a + 1, n - 1u);
    case ED_MOTION:
        return (n == 1u || (n == 2u && (a[1] == 2u || a[1] == 7u)) || (n == 3u && a[1] == 1u && a[2] <= 1u) ||
                (n == 6u && (a[1] == 3u || a[1] == 5u)) || (n == 4u && a[1] == 4u) || (n == 3u && a[1] == 6u)) &&
               a[0] < NTRK;
    case ED_SONG:
        return n && (a[0] == 1u || n == 1u);
    default:
        return 1;                                  /* variable payloads validate in their handler */
    }
}

static uint32_t ml_count(void)
{
    uint32_t i, n = 0;
    for (i = 0; i < ML_N; i++)
        n += ml_tab[3u * i] != 0u;
    return n;
}

/* (2.0, #44) PLAY from stopped: a track on a chain's part past its first (NOTES' cursor went there) plays the chain
 * from its first, as a pattern from its start. ((#30, the unit 2026-10-24: A's sound a user sound, ARCADE then put on
 * the track for D, PLAY on A: ARCADE until the song came round) a track on an entry with a sound plays that sound from
 * the start, unless it is on it already (its knobs turned since kept) */
static void chain_top(void)
{
    uint32_t k, e, b0, b1, u;
    const uint8_t *s;
    for (k = 0; k < NTRK; k++) {
        if ((e = trk_ent(k)) >= NENT)
            continue;
        if (ent_block(k, e, &b0, &b1) && e != b0) {
            (void)ent_go(k, b0);
            continue;
        }
        s = lists.snd[k][e];
        u = user_of(&trk[k]);
        if (s[0] && (u < UP_SLOTS ? s[0] != (0x80u | u) : s[0] != trk[k].eng_req + 1u || s[1] != trk[k].preset))
            esnd_go(k, e);
    }
}

/* (phase 5) SAVE > PATTERNS, the pool view: how many use pattern id: the entries naming it (the lists, the saved
 * projects), and a track on it that no entry of its names (0: it can be cleared) */
static uint32_t pool_refs(uint32_t id)
{
    uint32_t n, k;
    id %= BK_POOL;
    n = pat_refs(id, NTRK, 0);
    for (k = 0; k < NTRK; k++)
        n += trk_pid[k] == id + 1u && bank_cur(k) == BK_NONE;
    return n;
}

/* (2.0, #33, #44) COPY+'s numbers for track k's entry e's chain (e alone: its one), part by part as song_put takes
 * them: ids[i] the id + 1 (a REST's 0; NPAT + 1: the pool full); how many parts */
static uint32_t copy_ids(uint32_t k, uint32_t e, uint8_t *ids)
{
    uint32_t b0, b1, j, n;
    uint64_t taken = 0;
    ent_block(k, e, &b0, &b1);
    for (j = b0; j <= b1; j++) {
        n = ent_pat(k, j);
        ids[j - b0] = 0;
        if (n == PAT_NONE)
            continue;
        if ((n = pool_free_after(n, taken)) < NPAT)
            taken |= (uint64_t)1 << n;
        ids[j - b0] = (uint8_t)(n + 1u);
    }
    return b1 - b0 + 1u;
}

/* select track i (KNOB 1 on TRACKS, the editor): its sound, pages and pattern from now on */
static void track_select(uint32_t i)
{
    if (i >= NTRK || i == song.sel)
        return;
    sel_set((uint8_t)i);
    ui.entry_open = 0;
    ui.hot_t = 0;
    ui.cursor = 0;
    ui.bank = 0;
    sel_drop();                                        /* ((2.0) the other track's steps) */
    follow.hold = 0;                                   /* ((1.3) the roll follows the new track's playhead) */
    sync_reload = 1;
    ui.force = 1;
}

static void ed_handle(const uint8_t *f, uint32_t n)   /* f: the bytes between F0 and F7 */
{
    if (n < 4u)
        return;
    uint32_t cmd = f[3], i;
    const uint8_t *a = f + 4;
    uint32_t na = n - 4u;
    int16_t *vp;
    const param_desc_t *d;
    if (!ed_args_ok(cmd, a, na))
        return;
    if ((cmd >= ED_SMP_BEGIN && cmd <= ED_SMP_INFO) || (cmd >= ED_BACKUP_LIST && cmd <= ED_BACKUP_PUT))
        autosave_hold();                                /* (a transfer: no autosave meanwhile, project.c) */
    ed_begin(cmd);
    if (ed_ui_handle(cmd, a, na)) { ed_send(); return; }
    if (ed_backup_handle(cmd, a, na)) { ed_send(); return; }
    if (ed_fm6_handle(cmd, a, na)) { ed_send(); return; }
    if (ed_menu_handle(cmd, a, na)) { ed_send(); return; }
    if (ed_project_handle(cmd, a, na)) { ed_send(); return; }
    if (ed_song_handle(cmd, a, na)) { ed_send(); return; }
    switch (cmd) {
    case ED_MOTION: {
        track_t *t = &trk[a[0]]; uint32_t rc = 0;
        if (na > 1u && a[1] == 7u) {
            /* (the query with the kinds) */
        } else if (na > 1u) {
            if (a[1] == 1u) motion_set_enabled(t, a[2]);
            else if (a[1] == 2u) { load_begin(t, UNDO_PAT); motion_clear(t); load_end(t); }
            else if (a[1] == 3u) rc = motion_set_event(t, a[2] & 63u, ED_MID(a), (int16_t)ed_rv(a + 4));
            else if (a[1] == 4u && motion_param(ED_MID(a))) motion_delete_event(t, a[2] & 63u, ED_MID(a));
            else if (a[1] == 5u) rc = motion_set_lock(t, a[2] & 63u, ED_MID(a), (int16_t)ed_rv(a + 4));
            else if (a[1] == 6u && (a[2] < NSTEP || a[2] == 127u)) (void)motion_clear_locks(t, a[2]);
            else rc = 1;
            ui.force = 1;
        }
        ed_motion_reply(a[0], rc, na > 1u && a[1] >= 5u);
        break;
    }
    case ED_INFO: {
        /* the tags after the engines (tag, version, its bytes): (Skiff 2.0) their constant runs as tables */
        static const uint8_t TAGS1[] = {
            0x4d, 1, MOTION_MAX, 1,                     /* motion + chance v1 */
            0x42, 1, 3,                                 /* bounded full-backup read + restore */
            0x46, 1, FM6_NFACTORY, 0,                   /* FM6 patches: cmds 68..71 (no bank since 1.0.3) */
            0x53, 1, 3,                                 /* live sync: bit 0 WATCH while on keeps the shadow, bit 1 no
                                                         * RELOAD echo */
            0x50, 1, 3,                                 /* FM6 patches v2: bit 0 no bank (SLOT F1..F8, 8 OWN), bit 1
                                                         * user preset patches (FM6 target 3, backup id 9) */
            0x4E, 1, ED_MENU_N,                         /* MENU settings: cmds 72, 73; the items MENU_DESC offers */
            0x52, 1, 4,                                 /* RATCH: a step's ratchet (1..4 hits) after its chance */
            0x4C, 1, 1};                                /* 1.1 parameter locks: MOTION ops 5..7, the kinds after the
                                                         * records */
        static const uint8_t TAGS2[] = {
            0x43, 1, TC_COUNT,                          /* (Skiff W1) a step's FLAM, COND (TC_COUNT of them), NUDGE
                                                         * after its ratchet */
            0x4B, 1, 8,                                 /* (Skiff W3) the DRUM-X kit: KIT_GET, KIT_PUT, its 8 lanes */
            0x57, 1, ED_SKIFF_CAPS,                     /* (Skiff W3) TRANSPORT, PROJ_NAME (editor_project.c) */
            0x49, 1, P_COUNT & 127u, P_COUNT >> 7, P_E0 & 127u, P_E0 >> 7,   /* (Skiff 1.3) wide ids: P_COUNT and
                                         * P_E0 in two bytes; a track id from 128 on as scope 2 (ED_TID), a motion
                                         * record's from 128 on with bit 6 of its step byte */
            0x58, 1, ED_SONG2};                         /* (2.0) the song's LIST2, NEW, COPY+, CHAIN, ONCE, the pool's
                                                         * EMPTY, CLEAR UNUSED (editor_song.c; last: an editor before
                                                         * reads up to 49 01 only) */
        ed_str("FELUCCA " FELUCCA_VERSION, 24);
        ed_b(NENGINES);
        ed_b(P_COUNT > 127u ? 127u : P_COUNT);            /* ((1.3) more: INFO 49 01) */
        ed_b(G_COUNT);
        ed_b(NSTEP);
        ed_b(P_E0 > 127u ? 127u : P_E0);
        for (i = 0; i < NENGINES; i++)
            ed_str(ENGINES[i]->name, 8);
        ed_b(NTRK);                                       /* v3 */
        ed_b(CHAIN_ROWS);                                  /* v6 (an editor reads the tags after it only then) */
        ed_b(0x55); ed_b(1); ed_b(ed_ui_caps());             /* tagged preferences v1: commands 34..38 */
        ed_bs(TAGS1, sizeof TAGS1);
        {   /* (Skiff phase 6) light tracks: 54 01, the tracks past NHEAVY (a bit each), then the engines they may not
             * play (21 bits, 7 a byte: engines.c eng_allowed) */
            uint32_t tm = 0, em = 0;
            for (i = NHEAVY; i < NTRK; i++)
                tm |= 1u << i;
            for (i = 0; i < NENGINES; i++)
                em |= (uint32_t)!eng_allowed(NHEAVY, i) << i;
            ed_b(0x54); ed_b(1); ed_b(tm); ed_b(em & 127u); ed_b(em >> 7 & 127u); ed_b(em >> 14 & 127u);
        }
        ed_bs(TAGS2, sizeof TAGS2);
        break;
    }
    case ED_GET:
    case ED_SET:
        if (na < 2u || !(d = ed_desc(a[0], a[1], &vp)))
            return;
        if (cmd == ED_SET && na >= 4u) {
            if (a[0] == 1 && a[1] == G_ENGSEL) {          /* engine change: the safe path (1 without FELUCCA_FM4:
                                                           * DIGITAL's first preset, as FM6) */
                ed_load_t b;
                ed_load_before(&b);
                set_engine((uint32_t)clamp(ed_rv(a + 2), 0, NENGINES - 1));
                ed_load_after(&b);
            } else if (d->max > d->min) {
                *vp = (int16_t)enum_orig(d, clamp(ed_rv(a + 2), d->min, d->max));
                if (a[0] != 1u) {
                    (void)motion_capture(TSEL, ED_TID(a[0], a[1]), *vp);
                    load_extend(TSEL);                      /* (ui.c undo: an audition's values after G_ENGSEL) */
                }
            }
            ui.force = 1;
            ed_w.v[a[0] == 1u ? P_COUNT + a[1] : ED_TID(a[0], a[1])] = *vp;   /* the editor's own change: no push */
        }
        ed_b(a[0]);
        ed_b(a[1]);
        ed_v(*vp);
        break;
    case ED_DUMP:
        for (i = 0; i < ED_NV; i++)                       /* the editor gets them all here */
            ed_w.v[i] = *ed_val(i);
        ed_b(ed_eng(TSEL));
        ed_b(TSEL->preset);
        for (i = 0; i < P_COUNT; i++)
            ed_v(motion_base_value(TSEL, i));
        for (i = 0; i < G_COUNT; i++)
            ed_v(song.g[i]);
        break;
    case ED_DESC:
        if (na < 2u || !(d = ed_desc(a[0], a[1], &vp)))
            return;
        ed_b(a[0]);
        ed_b(a[1]);
        ed_b(d->fmt);
        ed_v(d->min);
        ed_v(d->max);
        ed_v(d->def);
        ed_str(d->label, 8);
        ed_str(PD_UNIT_OF(d), 8);
        if (d->fmt == F_ENUM && d->names)                  /* up to 24 (the matrix DST has 20) */
            for (i = 0; i <= (uint32_t)(d->max - d->min) && i < 24u; i++)
                ed_str(d->names[i], 8);
        break;
    case ED_STEP_GET:
    case ED_STEP_SET: {
        step_t *st;
        if (na < 1u || a[0] >= NSTEP)
            return;
        st = &TSEL->step[a[0]];
        if (cmd == ED_STEP_SET && na >= 9u) {
            ed_step_put(st, a + 1, na - 1u);
        }
        ed_w.st[a[0]] = ed_step_sig(&TSEL->step[a[0]]);
        ed_b(a[0]);
        ed_step_reply(&TSEL->step[a[0]]);
        break;
    }
    case ED_PRESET: {                                      /* engine, preset */
        ed_load_t b;
        if (na < 2u || a[0] >= NENGINES)
            return;
        ed_load_before(&b);
#if !FELUCCA_FM4 && FELUCCA_LEGACY
        if (a[0] == ENGI_DIGITAL)                          /* a DIGITAL preset (retired): its sound, as FM6 ((2.0) */
            fm4_load_preset(TSEL, a[1]);                   /* FM6's preset a[1]: set_engine_of) */
        else
#endif
        {
            if (a[0] == TSEL->eng_req || !set_engine(a[0]))   /* ((Skiff phase 6) refused: not its preset either) */
                apply_preset(a[1]);
        }
        ed_load_after(&b);
        ui.force = 1;
        ed_b(ed_eng(TSEL));
        ed_b(TSEL->preset);
        break;
    }
    case ED_PROJECT:                                       /* 0 = load, 1 = save, 2 = query; slot 0..3 */
        if (na < 2u || a[0] > 2u || a[1] >= 4u)
            return;
        if (a[0] == 1u) {
            if (ed_flash_stop() || project_save(a[1]))
                return;                              /* the legacy reply has no failure bit: do not confirm a failed save */
        }
        else if (a[0] == 0u)
            project_load(a[1] & 3u);
        ed_b(a[0]);
        ed_b(a[1] & 3u);
        ed_b(project_used(a[1] & 3u));
        break;
    case ED_NAMES:                                         /* preset names of an engine */
        if (na < 1u || a[0] >= NENGINES)
            return;
        ed_b(a[0]);
        ed_b(ENGINES[a[0]]->npresets);
        for (i = 0; i < ENGINES[a[0]]->npresets; i++)
            ed_str(ENGINES[a[0]]->presets[i].name, 12);
        for (i = 0; i < 2u; i++)                           /* then the two edit-page titles */
            ed_str(ENGINES[a[0]]->page_title[i], 8);
        break;
    case ED_SMP_BEGIN:                                     /* slot -> slot, rc */
    case ED_SMP_ERASE:
        if (na < 1u || a[0] >= SMP_USER_SLOTS || !flash_ok)
            return;
        ed_b(a[0]);
        ed_b(ed_flash_stop() || ed_smp_erase(a[0], cmd == ED_SMP_ERASE) ? 1u : 0u);
        break;
    case ED_SMP_WRITE: {                                   /* slot, off (3 x 7 bit), pack7 data -> slot, off, rc */
        uint32_t off, len, rc = 0, took;
        if (na < 5u || a[0] >= SMP_USER_SLOTS || !flash_ok)
            return;
        off = (uint32_t)a[1] | (uint32_t)a[2] << 7 | (uint32_t)a[3] << 14;
        len = ed_unpack7(a + 4, na - 4u, ed_smp_buf, 256u);
        if (off < SMP_USER_DATA || (off & 0xFFu) || !len || off + len > SMP_USER_SIZE)
            rc = 1;
        else if (usr_nz[a[0]] || !SMP_USER_HAS(a[0]))
            rc = 4;                                        /* slot in use: SMP_BEGIN first (voices read it) */
        else if (ed_flash_stop())
            rc = 1;
        else {
            if (!(off & 0xFFFu)) {                         /* first write into a sector: erase it */
                audio_silence();
#if BOARD_SMK37
                st_stock_release();                        /* (storage.c: the stock mapping's marker) */
#endif
                rc = fl_erase4k(ed_smp_slot(a[0]) + off, &took) ? 2u : 0u;
            }
            if (!rc && fl_write(ed_smp_slot(a[0]) + off, ed_smp_buf, len))
                rc = 3;
        }
        ed_b(a[0]);
        ed_b(off);
        ed_b(off >> 7);
        ed_b(off >> 14);
        ed_b(rc);
        break;
    }
    case ED_SMP_END:                                       /* slot, pack7 header -> slot, rc */
        if (na < 2u || a[0] >= SMP_USER_SLOTS || !flash_ok)
            return;
        ed_b(a[0]);
        ed_b((uint32_t)ed_smp_end(a[0], a + 1, na - 1u));
        break;
    case ED_SMP_INFO:                                      /* -> per slot: zones (0 = empty), name, data KiB */
        ed_b(SMP_SHOWN);
        ed_b(SMP_USER_SIZE / 1024u);
        for (i = 0; i < SMP_SHOWN; i++) {
            const smp_user_hdr_t *h = (const smp_user_hdr_t *)smp_user_xip(i);
            char nm[9];
            ed_b(usr_nz[i]);
            smp_user_name(i, nm);
            ed_str(nm, 8);
            ed_b(usr_nz[i] ? (h->data_len + 1023u) / 1024u : 0u);
        }
        break;
    case ED_UP_LIST: {                                     /* start, count -> start, count, total, per slot: used, engine, name */
        uint32_t s0, cnt;
        if (na < 2u)
            return;
        s0 = a[0];
        cnt = a[1] > 16u ? 16u : a[1];
        if (s0 >= UP_SLOTS)
            cnt = 0;
        else if (s0 + cnt > UP_SLOTS)
            cnt = UP_SLOTS - s0;
        ed_b(s0);
        ed_b(cnt);
        ed_b(UP_SLOTS);
        for (i = s0; i < s0 + cnt; i++) {
            char nm[13] = {0};
            uint32_t j, u = (uint32_t)up_used(i);
            for (j = 0; u && j < 12u; j++)
                nm[j] = up_rec(i)->name[j];
            ed_b(u);
            ed_b(u ? up_rec(i)->engine : 0u);
            ed_str(nm, 12);
        }
        break;
    }
    case ED_UP_GET: {                                      /* slot -> slot, used, engine, name, P_COUNT x v14, 16 x (note,
                                                            * flags), (v5) kind [, 16 x hi] (upreset.c up_parse) */
        int16_t v[P_COUNT];
        char nm[13] = {0};
        const up_rec_t *r;
        uint32_t u;
        if (na < 1u || a[0] >= UP_SLOTS)
            return;
        r = up_rec(a[0]);
        u = (uint32_t)up_used(a[0]);
        if (u)
            up_values(r, v);                               /* today's P_* order, clamped */
        for (i = 0; u && i < 12u; i++)
            nm[i] = r->name[i];
        ed_b(a[0]);
        ed_b(u);
        ed_b(u ? r->engine : 0u);
        ed_str(nm, 12);
        for (i = 0; i < P_COUNT; i++)
            ed_v(u ? v[i] : 0);
        for (i = 0; i < 16u; i++) {                        /* ((2.0) a version 6 record: none, rests) */
            ed_b(u && up_pat(r) ? r->note[i] & 0x7Fu : 0u);
            ed_b(u && up_pat(r) ? r->flags[i] & 0x7Fu : 0u);
        }
        ed_b(u && up_grid(r));                  /* kind: 1 = a drum grid, then bit 7 of each step's */
        for (i = 0; u && up_grid(r) && i < 16u; i++)   /* hits (bit 0) and accents (bit 1) */
            ed_b((uint32_t)(r->note[i] >> 7) | (uint32_t)(r->flags[i] >> 7) << 1);
        break;
    }
    case ED_UP_PUT: {                                      /* slot, engine, name, values, pattern -> slot, rc */
        static up_rec_t r;
        uint32_t slot = 0, rc;
        if (na < 1u)
            return;
        rc = (uint32_t)up_parse(a, na, &r, &slot);
        if (!rc && ed_flash_stop())
            rc = 2;
        if (!rc) {
            int16_t v[P_COUNT];
            up_values(&r, v);                              /* each value inside its range */
            up_set_sound(&r, v);                           /* ((2.0) stored as version 6: by id, its pattern not) */
            rc = up_put(slot, &r) ? 2u : 0u;
        }
        ed_b(a[0]);
        ed_b(rc);
        break;
    }
    case ED_UP_STORE: {                                    /* slot, name -> slot, rc */
        char nm[13] = {0};
        uint32_t n0, rc = 1;
        if (na < 1u)
            return;
        for (n0 = 0; 1u + n0 < na && a[1 + n0] && n0 < 13u; n0++)
            ;
        if (a[0] < UP_SLOTS && (!n0 || up_name_ok(a + 1, n0)) &&
            (1u + n0 == na || (2u + n0 == na && !a[1u + n0]))) {   /* "" = automatic name */
            for (i = 0; i < n0; i++)
                nm[i] = (char)a[1 + i];
            int r;
            r = ed_flash_stop() ? 2 : up_store(a[0], nm);
            rc = r ? 2u : 0u;
        }
        ed_b(a[0]);
        ed_b(rc);
        break;
    }
    case ED_UP_LOAD:                                       /* slot -> slot, rc */
        if (na < 1u)
            return;
        ed_b(a[0]);
        ed_b(a[0] < UP_SLOTS && !up_load(a[0]) ? 0u : 1u);
        break;
    case ED_UP_ERASE:
        if (na < 1u)
            return;
        ed_b(a[0]);
        ed_b(a[0] >= UP_SLOTS ? 1u : ed_flash_stop() || up_put(a[0], 0) ? 2u : 0u);
        break;
    case ED_WATCH: {                                       /* on -> on */
        uint32_t keep, v4was = ed_w.v4;
        if (na < 1u)
            return;
        keep = ed_w.on && ed_w.resets == usb.resets && (a[0] & 1u);   /* already watching: the changes not yet */
        ed_w.on = a[0] & 1u;                                          /* pushed stay pending (INFO 53 01 bit 0) */
        ed_w.v4 = (uint8_t)(ed_w.on && (a[0] & 2u));     /* v4: also TRACK_CHANGED; the reply says it is known */
        ed_w.resets = usb.resets;
        if (ed_w.on && !keep)
            ed_shadow();
        else if (keep && ed_w.v4 && !v4was)
            for (i = 0; i < ED_NT; i++)                    /* TRACK_CHANGED newly asked for: from the mix as it is */
                ed_w.tv[i] = trk[i / 3u].p[ED_TIDS[i % 3u]];
        ed_b(ed_w.on | ed_w.v4 << 1);
        break;
    }
    case ED_PING:
        ed_b(0);
        break;
    case ED_TRACK:                                         /* [track] -> selected, NTRK, per track: engine, preset, level, mute, armed */
        if (na >= 1u && a[0] < NTRK && a[0] != song.sel) {
            track_select(a[0]);
            if (ed_w.on)
                ed_shadow();                               /* the editor re-reads it: no RELOAD for this */
        }
        ed_b(song.sel);
        ed_b(NTRK);
        for (i = 0; i < NTRK; i++) {
            ed_b(ed_eng(&trk[i]));
            ed_b(trk[i].preset);
            ed_v(trk[i].p[P_LEVEL]);
            ed_b(trk[i].p[P_MUTE] != 0);
            ed_b((song.rec >> i) & 1u);
        }
        break;
    case ED_TRACK_MIX: {                                   /* track [, level v14, mute] -> track, level, mute */
        track_t *t;
        int16_t *lv;
        if (na < 1u || a[0] >= NTRK)
            return;
        t = &trk[a[0]];
        lv = &t->p[P_LEVEL];
        if (na >= 4u) {
            *lv = (int16_t)clamp(ed_rv(a + 1), 0, 127);
            t->p[P_MUTE] = (int16_t)(a[3] ? 1 : 0);
            ed_known(a[0], P_LEVEL);                       /* the editor's own change: no push */
            ed_known(a[0], P_MUTE);
            ui.force = 1;
        }
        ed_b(a[0]);
        ed_v(*lv);
        ed_b(t->p[P_MUTE] != 0);
        break;
    }
    case ED_TRACK_DUMP:                                    /* track -> track, engine, preset, P_COUNT x v14 */
        if (na < 1u || a[0] >= NTRK)
            return;
        ed_b(a[0]);
        ed_b(ed_eng(&trk[a[0]]));
        ed_b(trk[a[0]].preset);
        for (i = 0; i < P_COUNT; i++)
            ed_v(motion_base_value(&trk[a[0]], i));
        break;
    case ED_KIT_GET:                                       /* (Skiff W3) lane -> lane, wave, filter, snap, pitch mod, */
    case ED_KIT_PUT: {                                     /* drive, A's five, B's five (KIT_PUT: those set, then the same) */
        dx_lane_t *L = &dx_kit[a[0] & 7u];
        uint32_t i;
        if (cmd == ED_KIT_PUT) {
            L->mode = DX_MODE(a[1], a[2], a[3]) | (uint8_t)(a[4] << 5) | (a[5] ? DX_DRIVE : 0u);
            for (i = 0; i < DXP_N; i++) {
                L->a[i] = a[6 + i];
                L->b[i] = a[6 + DXP_N + i];
            }
            ui.force = 1;
        }
        ed_b(a[0] & 7u);
        ed_b(L->mode & 3u); ed_b((L->mode >> 2) & 3u); ed_b((L->mode >> 4) & 1u); ed_b((L->mode >> 5) & 3u);
        ed_b((L->mode & DX_DRIVE) != 0u);
        for (i = 0; i < DXP_N; i++)
            ed_b(L->a[i]);
        for (i = 0; i < DXP_N; i++)
            ed_b(L->b[i]);
        break;
    }
    case ED_TRACK_STEP: {                                  /* track, index [, step] -> track, index, step (as STEP_GET) */
        step_t *st;
        if (na < 2u || a[0] >= NTRK || a[1] >= NSTEP)
            return;
        st = &trk[a[0]].step[a[1]];
        if (na >= 10u)
            ed_step_put(st, a + 2, na - 2u);
        if (a[0] == song.sel)
            ed_w.st[a[1]] = ed_step_sig(st);
        ed_b(a[0]);
        ed_b(a[1]);
        ed_step_reply(st);
        break;
    }
    case ED_TRACK_PARAM: {                                 /* track, id [, v14] -> track, id, v14 ((1.3) an id from
                                                            * 128 on: bit 6 of the track byte is its bit 7) */
        track_t *t;
        uint32_t id = a[1] | (a[0] & 64u) << 1;
        if (na < 2u || (a[0] & 63u) >= NTRK || id >= P_COUNT)
            return;
        t = &trk[a[0] & 63u];
        d = ed_tdesc(t, id);
        if (na >= 4u) {
            if (d->max > d->min)                           /* as SET: clamped; a fixed value stays */
                t->p[id] = (int16_t)enum_orig(d, clamp(ed_rv(a + 2), d->min, d->max));
            (void)motion_capture(t, id, t->p[id]);
            ed_known(a[0] & 63u, id);
            ui.force = 1;
        }
        ed_b(a[0]);
        ed_b(a[1]);
        ed_v(t->p[id]);
        break;
    }
    case ED_SONG:                                          /* (Skiff phase 5: no project-slot song) always empty: */
        if (!na || a[0] > 3u) return;                      /* a set or PLAY refused (rc 1), STOP stops */
        if (a[0] == 3u) transport_req = 2;
        ed_b(a[0]); ed_b(a[0] == 1u || a[0] == 2u); ed_b(0);
        ed_b(0); ed_b(0); ed_b(0);
        break;
    default:
        return;
    }
    ed_send();
}

/* .. a user kit's: its slot + 1, 0 a kit of DRUM's own */
static uint32_t drum_user(const int16_t *p)
{
    uint32_t k = drum_kit_plays(p[P_E0]);
    return k >= DK_USR1 ? k - DK_USR1 + 1u : 0u;
}

static uint32_t con_num(const char **p, int *ok)        /* decimal or 0x hex */
{
    const char *s = *p;
    uint32_t v = 0, base = 10, d, n = 0;
    while (*s == ' ')
        s++;
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X'))
        s += 2, base = 16;
    for (;; s++, n++) {
        char c = *s;
        if (c >= '0' && c <= '9')
            d = (uint32_t)(c - '0');
        else if (base == 16 && c >= 'a' && c <= 'f')
            d = (uint32_t)(c - 'a' + 10);
        else if (base == 16 && c >= 'A' && c <= 'F')
            d = (uint32_t)(c - 'A' + 10);
        else
            break;
        v = v * base + d;
    }
    *ok = n > 0;
    *p = s;
    return v;
}

/* stored step o unfolded into d, p the one before unfolded (0: none): a TIE as the notes p can tie, tied */
static void ed_unfold(step_t *d, const step_t *o, const step_t *p)
{
    uint32_t k, m;
    *d = *o;
    if (o->time != ST_TIE || !p)
        return;
    d->time = ST_NOTE;
    d->n = d->hit = d->acc = 0;
    for (m = ed_cont(p), k = 0; k < p->n; k++)
        if ((m >> k) & 1u) {
            d->note[d->n] = p->note[k];
            d->acc |= (uint8_t)(1u << d->n++);
        }
}

/* the copy folded back into t's steps 1..len and written at once; the steps in keep (bit i) stay unfolded (step entry
 * goes on writing them). A step that can be a TIE is one (a pattern left without overlaps: as 1.4 has it) */
static void ed_close(track_t *t, step_t *w, uint32_t len, uint64_t keep)
{
    step_t o, po, pu, cur, last = w[len ? len - 1u : 0u];
    uint32_t i, k, m, held, same;
    for (i = 0; i < len; i++) {
        cur = w[i];
        ed_unfold(&o, &t->step[i], i ? &po : 0);
        for (held = i > 0u && !cur.hit && cur.time == ST_NOTE, m = held ? ed_cont(&pu) : 0u, k = 0; held && k < cur.n; k++)
            held = step_tied(&cur, k) && note_at(&pu, cur.note[k]) >= 0 && ((m >> note_at(&pu, cur.note[k])) & 1u);
        held = held && (uint32_t)__builtin_popcount(m) == cur.n && !((keep >> i) & 1u);   /* (what goes on: just what
                                                       * sounded before) */
        same = !memcmp(&cur, &o, sizeof o);
        if (same && t->step[i].time == ST_TIE && held)
            w[i] = t->step[i];                          /* (a TIE not changed: its bytes) */
        else if (held && cur.n) {
            w[i].time = ST_TIE;                         /* (its notes' bytes 0: a TIE ignores them) */
            w[i].n = w[i].acc = 0;
            memset(w[i].note, 0, sizeof w[i].note);
        } else if (same && t->step[i].time != ST_TIE)
            w[i] = t->step[i];                          /* (not changed: its bytes) */
        po = o;
        pu = cur;
    }
    fm1_irq_off();                                      /* the audio ISR must not see half a pattern */
    memcpy(t->step, w, len * sizeof *w);
    fm1_irq_on();
    if (len)                                            /* ((2.0, #44) a note no longer at the part's end: its tail */
        (void)chain_tails(trk_index(t), &last, 0, 0, 0, 0);   /* in a chain's next part goes) */
}

/* "14 NOTES" / "1 NOTE" after what b holds (a ", " between them) */
static void say_count(char *b, uint32_t sz, uint32_t n, const char *what)
{
    uint32_t i = str_len(b);
    if (i)
        str_cpy(b + i, ", ", sz - i);
    i = str_len(b);
    fmt_int(b + i, (int32_t)n);
    i = str_len(b);
    str_cpy(b + i, what, sz - i);
    if (n != 1u) {
        i = str_len(b);
        str_cpy(b + i, "S", sz - i);
    }
}

static void shift_mark(void)
{
#if BOARD_SMK37
    if (smk_sh_t0)
        smk_sh_t0 |= 2u;
#endif
    if (ui.home_t0)
        ui.home_t0 |= 2u;
}

/* Skiff: SAVE held, or OCT- in the undo window: back one copy; OCT+ in the window: forward one (its redo). Each opens
 * the window again (ui.undo_w: ui_input.c takes OCT- / OCT+ while it is open): the undo box says what and how far back
 * (BLOCKS, ui_take.c), else the header */
static void undo_step(int redo)
{
    undo_t *c;
    char b[24];
    if (redo ? !undo_back : undo_back >= undo_n) {
        ui_message(redo ? "NOTHING TO REDO" : "NOTHING TO UNDO");
        ui.undo_w = undo_n ? UNDO_WIN : 0u;       /* (the other way may still go) */
        return;
    }
    if (redo)
        undo_back--;
    c = &undo_ring[(undo_top + UNDO_N - undo_back) % UNDO_N];
    if (!undo_swap(c)) {
        if (redo)
            undo_back++;
        return;
    }
    if (!redo)
        undo_back++;
    if (take_box_fits()) {
        take_box_undo(redo, (uint32_t)c->trk - 1u, c->name);
    } else {                                      /* "UNDO T1 TAKE", then the keys */
        str_cpy(b, redo ? "REDO T1 " : "UNDO T1 ", sizeof b);
        b[6] = (char)('1' + (c->trk - 1u) % NTRK);
        ui_say(b, c->name);
        str_cpy(ui.msg2, "[OCT-] BACK  OCT+ REDO", sizeof ui.msg2);
    }
    ui.undo_w = UNDO_WIN;
}

/* lane l of step s from now on is its hit alone: the step's lane notes become hits (nothing sounds different),
 * a note of another pitch on the lane (a low tom 41) becomes the lane's own */
static void grid_own(step_t *s, uint32_t l)
{
    uint32_t k, j = 0;
    step_to_grid(s);
    for (k = 0; k < s->n; k++)
        if (drum_lane(s->note[k]) == l)
            s->hit |= (uint8_t)(1u << l);
        else
            s->note[j++] = s->note[k];
    for (k = j; k < 4u; k++)
        s->note[k] = 0;
    s->n = (uint8_t)j;
}

/* (2.0, #25) notes only go on at st: a TIE, or a NOTE step whose notes are all tied */
static int step_tie(const step_t *st)
{
    return st->time == ST_TIE || (st->time == ST_NOTE && st->n && !st->hit && step_ties(st) == (1u << st->n) - 1u);
}

static uint32_t rng(void)
{
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

                                                                                      * 1/8 1/16D 8T 1/16 16T 1/32 */
static const uint8_t *enum_order(const param_desc_t *d)
{
    return d->names == N_DIV ? DIV_ORDER : d->names == N_SLDIV ? SLDIV_ORDER : d->names == N_DTIME ? DTIME_ORDER : 0;
}

/* .. KNOB 2's turn order: --, ((2.0, #32, the user's pick 1A) NEW: an empty entry's), REST, 01 .. 64, (NEW: a used
 * entry's), COPY, ((#33) COPY+), CLEAR, ((#30) SOUND, NO SOUND): a pick's place (own: an empty entry's NEW first), and
 * back; a place that is not its value's own (spick_pos) is passed over */
static uint32_t spick_pos(uint32_t v, uint32_t own)
{
    return v == SPICK_NEW && !own ? 1u : v == PAT_REST ? 2u : v ? v + 2u : 0u;
}

static int32_t len_get(const track_t *t, uint32_t i)
{
    uint32_t k, n;
    int16_t v;
    for (k = 0; k < t->step[i].n && (!sel_voice(i, k) || step_tied(&t->step[i], k)); k++)
        ;
    n = k < t->step[i].n ? note_span(t, i, k) : step_span(t, i);
    if (k < t->step[i].n && i + n == (uint32_t)t->p[P_SLEN])   /* ((2.0, #44) on into a chain's next part: all of it */
        n += chain_tail_len(trk_index(t), t->step[i].note[k]);
    if (n > 1u)
        return LEN_STEPS + (int32_t)n - 2;
    if (!motion_lock_get(t, i, P_SGATE, &v))
        v = motion_base_value(t, P_SGATE);
    return v;
}

/* HOME: what KNOB k edits: the engine's four main parameters */
static const param_desc_t *home_param(uint32_t k, int16_t **vp)
{
    uint32_t id = ENGINES[TSEL->eng_req % NENGINES]->knob[k & 3u];
    *vp = &TSEL->p[id];
    return track_desc(TSEL, id);
}

/* where in its pass the playing step is in time, 0.. (the header's bar.beat): FWD the step itself */
static uint32_t seq_at(const track_t *t)
{
    return t->p[P_DIR] == DIR_FWD || !t->seq_cnt ? t->seq_idx : t->seq_cnt - 1u;
}

static void ne_hgrad(int32_t x, int32_t y, int32_t w, int32_t h, const uint16_t *st, uint32_t n)
{
    int32_t i;
    for (i = 0; i < w; i++)
        cv_rect(x + i, y, 1, h, ne_ramp(st, n, w > 1 ? i * 1000 / (w - 1) : 0));
}

static void cv_key_row(int32_t x0, int32_t x1, int32_t y, const khint_t *h, uint32_t n, uint32_t on, uint16_t under)
{
    uint32_t i, words = n;                         /* hints 0 .. words-1 keep their word */
    int32_t w, gap, x = x0;
    for (;;) {
        w = 0;
        for (i = 0; i < n; i++)
            w += kh_w(h[i].key, i < words ? h[i].act : 0);
        if (w + 6 * (int32_t)(n - 1u) <= x1 - x0 || !words)
            break;
        words--;
    }
    gap = n > 1u ? (x1 - x0 - w) / (int32_t)(n - 1u) : 0;
    for (i = 0; i < n; i++) {
        if (n > 1u && i + 1u == n)
            x = x1 - kh_w(h[i].key, i < words ? h[i].act : 0);   /* the last one flush right */
        x = cv_key_hint(x, y, h[i].key, i < words ? h[i].act : 0, (on >> i) & 1u, under) + gap;
    }
}

/* a card's gauge as an 80s dash bargraph: slanted segments 4 px apart, 5 rows, lit up to the value cyan, violet, pink
 * as they climb, the rest dark glass (the hot card: INK on its dusk) */
static void ne_dash(int32_t x, int32_t y, int32_t w, int32_t ratio, int hot)
{
    const uint16_t st[3] = {T_ACCENT, NE_VIOLET, T_THEME};
    int32_t n = (w - 2) / 4, lit = (n * (ratio > 1000 ? 1000 : ratio) + 500) / 1000, k, r;
    for (k = 0; k < n; k++) {
        uint16_t c = k < lit ? (hot ? T_INK : ne_ramp(st, 3, n > 1 ? k * 1000 / (n - 1) : 0))
                             : hot ? ux_mix(T_INK, NE_ORANGE, 55) : ux_mix(T_SURF, T_TEXT, 10);
        for (r = 0; r < 5; r++)
            cv_rect(x + k * 4 + (4 - r) / 2, y + r, 3, 1, c);
    }
}

/* an action's column (act_cols): picked, the OCT+ keycap (accent while it would do something); else "--" */
static void draw_act_column(uint32_t c, const char *label, uint32_t vr, uint32_t icon)   /* icon: ICON_AUTO = by label */
{
