}

/* a time's half-life (an envelope's DECAY, RELEASE: 99 % of the way in TIME_MS_X10, e^-4.6; half of it in 0.15 of
 * that): "T1/2 12 MS" */
static void qk_halflife(char *b, int16_t p)
{
    uint32_t ms10 = TIME_MS_X10[p & 127] * 15u / 100u;
    str_cpy(b, "T1/2 ", 8);
    if (ms10 < 100u)
        fmt_fix(b + 5, (int32_t)ms10, 1);
    else
        fmt_int(b + 5, (int32_t)((ms10 + 5u) / 10u));
    str_cpy(b + str_len(b), " MS", 4);
}

/* (Skiff 1.3) FX > INSERT and INSERT 2: the TYPE as fx.c track_insert runs it, in DRIVE's look (pg_curve_graph). The
 * drives and CRUSH: the transfer (DRIVE / BITS, blended by MIX) across the input, and a sine's cycle through it, TONE /
 * LPF and LEVEL (CRUSH: its held samples); the swept ones: the sweep over one of its cycles (PHASR and FLANG a triangle,
 * FLANG's squared, CHOR a sine, as deep as DEPTH) and two of its cycles at the right. OFF or MIX 0: the straight line */
static int32_t pg_ins_curve(const pg_curve_t *k, int32_t x)
{
    int32_t y;
    if (!k->type || !k->mix)
        return x;
    if (k->type >= IT_PHASER) {                      /* (x: the place in the sweep's cycle) */
        uint32_t ph = (uint32_t)(x + 32768) << 16;      /* (one whole cycle across: the end wraps to the start) */
        int32_t s = k->type == IT_CHORUS ? osc_sine(ph) : (int32_t)ins_tri(ph) - 32768;
        if (k->type == IT_FLANGER)
            s = (int32_t)(((uint32_t)(s + 32768) * (uint32_t)(s + 32768)) >> 16) - 32768;
        return s * k->b / 127;
    }
    if (k->type == IT_CRUSH)
        y = ins_shape(IT_CRUSH, x, ins_bits_sh(k->a));
    else
        y = (ins_shape(k->type, ((x >> 3) * (4096 + k->a * k->a * 3)) >> 9, 0) * LEVEL_Q12[k->c & 127]) >> 12;
    return x + (int32_t)(((int64_t)(clamp(y, -40000, 40000) - x) * k->mix) >> 15);
}

static const char *song_act_name(void)
{
    static char b[28] __attribute__((section(".pool")));   /* (.pool: off the ISR's merged globals) */
    uint32_t p = song_pick(), id = ent_pat(song.sel, sg.entry), n, b0, b1;
    if (!p)
        return "PLAY";
    if (p == SPICK_CLEAR)
        return "CLEAR";
    if (p == SPICK_NOSND)
        return "SET NO SOUND";
    if (p == SPICK_SOUND) {
        str_cpy(b, "SET SOUND ", sizeof b);
        sound_name(TSEL, b + 10);                    /* (16 at most) */
        return b;
    }
    if (p == PAT_REST)
        return "SET REST";
    if (p == SPICK_NEW) {                        /* (the first free number: none, NEW alone) */
        str_cpy(b, "NEW", sizeof b);
        if ((n = pool_alloc()) < NPAT) {
            b[3] = ' ';
            pat_num(b + 4, n);
        }
        return b;
    }
    if (p == SPICK_COPYP && ent_block(song.sel, sg.entry, &b0, &b1) &&
        (n = ent_free_after(song.sel % NTRK, sg.entry % NENT)) < NENT) {   /* ((#44) a chain's: "COPY A-B TO F-G") */
        str_cpy(b, "COPY A-B TO F-G", sizeof b);
        b[5] = (char)('A' + b0), b[7] = (char)('A' + b1);
        b[12] = (char)('A' + n), b[14] = (char)('A' + n + b1 - b0);
        return b;
    }
    if (p == SPICK_COPY || p == SPICK_COPYP) {
        n = id != PAT_NONE ? pool_alloc_after(id) : NPAT;
        str_cpy(b, "COPY ", sizeof b);
        pat_num(b + 5, id);
        if (n < NPAT) {
            str_cpy(b + 7, " TO ", sizeof b - 7u);
            pat_num(b + 11, n);
            if (p == SPICK_COPYP && (n = ent_free_after(song.sel % NTRK, sg.entry % NENT)) < NENT) {
                str_cpy(b + 13, " AT ", sizeof b - 13u);
                b[17] = (char)('A' + n);
                b[18] = 0;
            }
        }
        return b;
    }
    str_cpy(b, "SET ", sizeof b);
    pat_num(b + 4, p - 1u);
    return b;
}

/* osc 2 / 3 increment: the base pitch + semitones + cents, with the voice's fine factor (unison,
 * TUNE) that m->inc carries */
static uint32_t trio_inc(int32_t pitch16, int32_t semi, int32_t ct, int32_t fine)
{
    return cents_inc(pitch16 + semi * 16, ct, fine);
}

/* f: cycles / sample Q32 (< 0.5), q: Q8 (> 0) */
static void px_svf_coef(px_svf_t *c, uint32_t f, uint32_t q8)
{
    int32_t g = px_fasttan(f);
    uint32_t r = (uint32_t)((((uint64_t)1 << 36) + q8 - 1u) / q8);       /* 1 / q, rounded up */
    uint64_t den = ((uint64_t)1 << 28) + (((uint64_t)r * (uint32_t)g) >> 28) + (((uint64_t)g * (uint32_t)g) >> 28);
    uint32_t d24 = (uint32_t)((den + 15u) >> 4);         /* Q24, rounded up */
    uint32_t h = (uint32_t)(((uint64_t)1 << 54) / d24);  /* Q30, rounded down */
    c->g = g;
    c->rpg = (int32_t)(r + (uint32_t)g);
    c->gh = (int32_t)(((uint64_t)h * (uint32_t)g) >> 28);
}

/* the lane voice v plays, 0 when it plays none (any more) */
static drum_lane_t *drum_lane_of(track_t *t, const voice_t *v)
{
    drum_lane_t *K = drum_kit_of(t), *L;
    uint32_t i = (uint32_t)(v - t->v);
    if (!K || i >= NVOICE)
        return 0;
    L = &K[(uint32_t)v->s[0] & (DV_NLANE - 1u)];
    return L->owner == i + 1u ? L : 0;
}

/* what the cards and the panel show changed (the lane's LEVL: ui_graph.c graph_signature hashes the track's values) */
static uint32_t dx_sig(void)
{
    const dx_lane_t *L = &dx_kit[dx_ui_lane & 7u];
    uint32_t h = (uint32_t)dx_ui_lane * 31u + dx_ui_win * 977u + L->mode * 131u, i;
    for (i = 0; i < DXP_N; i++)
        h = (h ^ (uint32_t)L->a[i] << 8 ^ L->b[i]) * 16777619u;
    return h;
}

/* KNOB k (0..3) turned s on sheet pg (0 OPERATOR, 1 ALL OPS) */
static void fm_knob(uint32_t pg, uint32_t k, int32_t s)
{
    track_t *t = TSEL;
    uint32_t tr = fm_tr(), w = fm_ui[1 + pg] % FM_NWIN, i, mx;
    const fm_field_t *f = &FM_F[pg & 1u][w][k & 3u];
    uint8_t v[FP_SIZE + 1u];
    int32_t d = s > 0 ? 1 : -1, x;
    if (!f->label || t->eng_req % NENGINES != ENGI_FM6)
        return;
    i = fm_at(pg, f);
    mx = fm6_max(i);
    memcpy(v, fm6_patch[tr], sizeof v);
    switch (f->fmt) {
    case FMF_RATIO: {                                   /* one knob over both modes: x0.5 .. x31, 1 .. 1K HZ */
        uint8_t *op = v + (i / FP_OP) * FP_OP;
        x = clamp(fm_ratio_pos(op) + accel(EN_K1 + k, s, 36), 0, 35);
        op[FP_MODE] = (uint8_t)(x >= 32);
        op[FP_FC] = (uint8_t)(x >= 32 ? x - 32 : x);
        break;
    }
    case FMF_ALG:                                       /* what plays, into the patch; ALGO (EDIT 1) to PAT */
        v[FP_ALG] = (uint8_t)clamp((int32_t)fm6_alg_of(t) + accel(EN_K1 + k, s, 32), 0, 31);
        t->p[P_E0] = 0;
        break;
    case FMF_FB:                                        /* the same: FEEDBACK (EDIT 1) to 0 */
        v[FP_FB] = (uint8_t)clamp(clamp((int32_t)v[FP_FB] + t->p[P_E1], 0, 7) + d, 0, 7);
        t->p[P_E1] = 0;
        break;
    default:
        v[i] = (uint8_t)clamp((int32_t)v[i] + (mx > 7u ? accel(EN_K1 + k, s, (int32_t)mx) : d), 0, (int32_t)mx);
        break;
    }
    fm6_set_patch(tr, v);
    fm6_adopt(tr);
}

static void fm_bp(fm_env_line_t *l, int32_t i, int32_t v)
{
    if (l->n < FM_NBP) {
        l->i[l->n] = i;
        l->v[l->n++] = v;
    }
}

/* line l's level at column x: between its breakpoints */
static int32_t fm_at_x(const fm_env_line_t *l, int32_t x)
{
    uint32_t j;
    for (j = 1; j < l->n; j++)
        if (x <= l->x[j]) {
            int32_t xa = l->x[j - 1u], xb = l->x[j];
            return xb <= xa ? l->v[j] : l->v[j - 1u] + (l->v[j] - l->v[j - 1u]) * (x - xa) / (xb - xa);
        }
    return l->n ? l->v[l->n - 1u] : 0;
}

/* the handles on line l's stage ends (stages 0..3); filled: hot (0xFF none) */
static void fm_handles(const fm_env_line_t *l, uint32_t hot, int32_t (*y)(int32_t))
{
    uint32_t j;
    for (j = 0; j < 4u; j++)
        if (l->end[j] != 0xFFu)
            fm_ring(FM_X0 + l->x[l->end[j]], y(l->v[l->end[j]]), j == hot);
}
